package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
	}

	an := 0

	countOnes := func(slice []int) int {
		c := 0
		for _, v := range slice {
			if v == 1 {
				c++
			}
		}
		return c
	}

	indexOfOne := func(slice []int) int {
		for i, v := range slice {
			if v == 1 {
				return i
			}
		}
		return -1
	}

	for countOnes(a) > 0 {
		idx := indexOfOne(a)
		c1 := countOnes(a)
		if idx+c1 > an {
			an = idx + c1
		}
		// delete element at idx
		a = append(a[:idx], a[idx+1:]...)
	}

	if an > len(a) {
		fmt.Println(an)
	} else {
		fmt.Println(len(a))
	}
}

